:root {
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --gold: #ffd469;
  --gold-deep: #ff9a2e;
  --cyan: #7fe7ff;
  --pink: #ff5fd2;
  --ink: #0a0610;
  --display: Impact, "Arial Black", "Helvetica Neue", "DejaVu Sans", sans-serif;
  --body: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #0a0610;
  color: #fff;
  font-family: var(--body);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
  touch-action: none;
}

body.playing { cursor: none; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

.hidden { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }

/* ---------------- HUD ---------------- */

#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
  padding: calc(var(--safe-t) + 18px) calc(var(--safe-r) + 22px) calc(var(--safe-b) + 18px) calc(var(--safe-l) + 24px);
  transition: opacity .35s ease;
  --chain: #7fe7ff;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.score-block { line-height: 1; filter: drop-shadow(0 2px 6px rgba(0,0,0,.55)); }

.eyebrow {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .3em;
  color: var(--gold);
  opacity: .78;
}

#score {
  font-family: var(--display);
  font-size: clamp(34px, 5.2vw, 56px);
  letter-spacing: .02em;
  margin-top: 4px;
  font-variant-numeric: tabular-nums;
  color: #fff9ea;
  text-shadow: 0 2px 0 rgba(90, 34, 0, .55), 0 0 26px rgba(255, 190, 90, .28);
}

.best-line {
  margin-top: 5px;
  font-size: 10px;
  letter-spacing: .18em;
  font-weight: 700;
  color: rgba(255, 235, 195, .5);
}

.best-line span { color: rgba(255, 220, 150, .85); }

.top-right { display: flex; flex-direction: column; align-items: flex-end; gap: 10px; }

.hearts { display: flex; gap: 4px; filter: drop-shadow(0 2px 6px rgba(0,0,0,.4)); }

.hearts svg { width: clamp(19px, 2.8vw, 25px); height: auto; display: block; overflow: visible; }

.hearts .heart { transition: transform .25s ease, opacity .25s ease; transform-origin: center; }
.hearts .heart.lost { opacity: .2; transform: scale(.78); filter: grayscale(1); }
.hearts .heart.pulse { animation: heart-pop .45s cubic-bezier(.2, 1.6, .4, 1); }

@keyframes heart-pop {
  0% { transform: scale(1); }
  45% { transform: scale(1.45) rotate(-8deg); }
  100% { transform: scale(1); }
}

.icon-row { display: flex; gap: 7px; }

.icon-btn {
  pointer-events: auto;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(255, 225, 170, .18);
  background: rgba(22, 12, 26, .55);
  color: rgba(255, 240, 215, .82);
  backdrop-filter: blur(6px);
  cursor: pointer;
  transition: background .18s ease, transform .18s ease, border-color .18s ease;
}
.icon-btn:hover { background: rgba(48, 27, 55, .8); border-color: rgba(255, 215, 130, .45); }
.icon-btn:active { transform: scale(.92); }
.icon-btn svg { width: 18px; height: 18px; fill: currentColor; }

/* combo ring */

.combo {
  position: absolute;
  top: calc(var(--safe-t) + 10px);
  left: 50%;
  transform: translate(-50%, -12px) scale(.85);
  opacity: 0;
  transition: opacity .22s ease, transform .22s cubic-bezier(.2, 1.2, .4, 1);
  pointer-events: none;
}

.combo.show { opacity: 1; transform: translate(-50%, 0) scale(1); }

.combo-ring { position: relative; width: 76px; height: 76px; }

.combo-ring svg { width: 100%; height: 100%; transform: rotate(-90deg); overflow: visible; }

.combo-track {
  fill: rgba(12, 6, 18, .35);
  stroke: rgba(255, 255, 255, .1);
  stroke-width: 5;
}

#comboRing {
  fill: none;
  stroke: var(--chain);
  stroke-width: 5;
  stroke-linecap: round;
  stroke-dasharray: 201.06;
  stroke-dashoffset: 0;
  filter: drop-shadow(0 0 5px var(--chain));
  transition: stroke .25s ease;
}

.combo-center {
  position: absolute;
  inset: 0;
  display: grid;
  place-content: center;
  text-align: center;
  line-height: 1;
}

#comboMult {
  font-family: var(--display);
  font-size: 22px;
  letter-spacing: .01em;
  color: #fff;
  text-shadow: 0 0 10px var(--chain), 0 2px 4px rgba(0,0,0,.5);
}

.combo-cap { margin-top: 3px; font-size: 8px; font-weight: 800; letter-spacing: .16em; color: var(--chain); opacity: .9; }

/* hint + storm */

.hint {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-b) + 112px);
  transform: translateX(-50%);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .28em;
  color: rgba(255, 240, 215, .72);
  text-shadow: 0 2px 8px rgba(0,0,0,.8);
  white-space: nowrap;
  transition: opacity .7s ease;
  animation: hint-breathe 2.4s ease-in-out infinite;
}

.hint.fade { opacity: 0; }

@keyframes hint-breathe { 0%, 100% { opacity: .5; } 50% { opacity: .95; } }

.storm-panel {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-b) + 18px);
  transform: translateX(-50%);
  width: min(380px, 76vw);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
}

.storm-meta {
  width: 100%;
  display: flex;
  justify-content: space-between;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .24em;
  color: rgba(255, 240, 215, .6);
}

#stormPct { color: rgba(150, 225, 255, .85); font-variant-numeric: tabular-nums; }

.storm-bar {
  width: 100%;
  height: 11px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .08);
  border: 1px solid rgba(255, 255, 255, .14);
  box-shadow: inset 0 2px 6px rgba(0,0,0,.5);
  overflow: hidden;
}

#stormFill {
  height: 100%;
  width: 0%;
  border-radius: inherit;
  background: linear-gradient(90deg, #35b8ff, #8b7bff 55%, #ff5fd2);
  box-shadow: 0 0 14px rgba(90, 200, 255, .8);
  transition: width .16s linear;
}

.storm-btn {
  pointer-events: auto;
  margin-top: 2px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 18px;
  border-radius: 999px;
  border: 1px solid rgba(140, 220, 255, .22);
  background: rgba(20, 12, 26, .6);
  color: rgba(200, 235, 255, .42);
  font-family: var(--body);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .18em;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: all .2s ease;
}

