  scrollbar-width: none;
  padding: clamp(24px, 4.4vw, 48px) clamp(20px, 4vw, 52px) clamp(22px, 3.4vw, 36px);
  text-align: center;
  border-radius: 30px;
  background:
    radial-gradient(ellipse at 50% -10%, rgba(255, 170, 70, .14), transparent 55%),
