  border: 1px solid rgba(255, 208, 120, .22);
  box-shadow: 0 34px 90px rgba(0, 0, 0, .65), inset 0 1px 0 rgba(255, 255, 255, .1), inset 0 0 80px rgba(255, 140, 55, .04);
  animation: panel-in .45s cubic-bezier(.2, 1, .35, 1);
}

.panel::-webkit-scrollbar { display: none; }

@keyframes panel-in {
  from { opacity: 0; transform: translateY(18px) scale(.96); }
  to { opacity: 1; transform: none; }
}

.panel::after {
  content: "";
  position: absolute;
  inset: 8px;
  border-radius: 24px;
  border: 1px solid rgba(255, 225, 170, .06);
  pointer-events: none;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .32em;
