  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 3px 0 rgba(0, 52, 82, .55)) drop-shadow(0 18px 34px rgba(80, 200, 255, .3));
}

.tagline {
  margin: 18px 0 0;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .52em;
  text-indent: .52em;
  color: rgba(160, 230, 255, .85);
  text-shadow: 0 0 18px rgba(90, 210, 255, .35);
}

.lede {
  max-width: 460px;
