  font-size: clamp(13px, 1.45vw, 15px);
  line-height: 1.6;
  color: rgba(255, 239, 218, .62);
}

.features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: clamp(18px, 3vw, 28px) 0 clamp(20px, 3vw, 30px);
  padding: 14px 4px;
  border-top: 1px solid rgba(255, 220, 160, .1);
  border-bottom: 1px solid rgba(255, 220, 160, .1);
}

.feature { padding: 4px 8px; position: relative; }
.feature + .feature::before {
  content: "";
  position: absolute;
  left: -4px;
  top: 10%;
  height: 80%;
  width: 1px;
  background: linear-gradient(transparent, rgba(255, 220, 160, .13), transparent);
}

.feature-icon {
  font-size: 22px;
  line-height: 1;
  margin-bottom: 7px;
  font-weight: 900;
}
.swipe-icon { color: var(--gold); transform: rotate(-16deg); }
.chain-icon { color: var(--cyan); text-shadow: 0 0 12px rgba(90, 220, 255, .6); font-size: 26px; }
.storm-icon { color: var(--pink); text-shadow: 0 0 12px rgba(255, 90, 210, .55); }

.feature-name { font-size: 9px; font-weight: 900; letter-spacing: .24em; color: rgba(255, 245, 225, .86); }
.feature-copy { margin-top: 5px; font-size: 10px; line-height: 1.45; color: rgba(255, 235, 210, .42); }

.btn {
  position: relative;
  border: none;
  cursor: pointer;
  font-family: var(--body);
  font-weight: 900;
  border-radius: 999px;
  letter-spacing: .22em;
  transition: transform .12s ease, box-shadow .18s ease, background .18s ease;
  -webkit-tap-highlight-color: transparent;
}

.btn-primary {
  padding: 16px 62px;
  font-size: clamp(17px, 2.1vw, 21px);
  color: #2b1400;
  text-indent: .22em;
  background: linear-gradient(180deg, #fff1b8, #ffc648 42%, #ff9a1e 100%);
  box-shadow: 0 6px 0 #8d4300, 0 16px 34px rgba(255, 140, 20, .3), inset 0 1px 0 #fff9d8;
}

.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 0 #8d4300, 0 20px 42px rgba(255, 150, 20, .42), inset 0 1px 0 #fff9d8; }
