.button-stack { display: flex; flex-direction: column; align-items: center; gap: 10px; margin-top: 26px; }
.button-stack .btn-primary { width: 100%; max-width: 280px; padding: 14px 30px; font-size: 16px; }
.button-stack .btn-ghost { width: 100%; max-width: 280px; }

.final-score { margin-top: 18px; }
.final-score #finalScore {
  font-family: var(--display);
  font-size: clamp(48px, 8vw, 74px);
  line-height: 1;
  margin-top: 5px;
  color: #fff8e8;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 3px 0 rgba(90, 30, 0, .5), 0 0 32px rgba(255, 180, 80, .3);
}

.new-best {
  display: inline-block;
  margin-top: 8px;
  padding: 4px 12px;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .22em;
  color: #2b1400;
  background: linear-gradient(180deg, #fff1b8, #ffc648);
  box-shadow: 0 0 18px rgba(255, 200, 80, .45);
  animation: best-glow 1.3s ease-in-out infinite;
}

@keyframes best-glow {
  0%, 100% { box-shadow: 0 0 12px rgba(255, 200, 80, .3); }
  50% { box-shadow: 0 0 26px rgba(255, 210, 90, .7); }
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
  margin-top: 22px;
  padding: 14px 4px;
  border-top: 1px solid rgba(255, 220, 160, .1);
  border-bottom: 1px solid rgba(255, 220, 160, .1);
}

.stat { display: flex; flex-direction: column; gap: 4px; }
.stat span {
  font-family: var(--display);
  font-size: clamp(20px, 3vw, 27px);
  line-height: 1;
  color: #ffe9bd;
  font-variant-numeric: tabular-nums;
}
.stat small { font-size: 7.5px; font-weight: 900; letter-spacing: .18em; color: rgba(255, 225, 185, .4); }

.button-row { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-top: 24px; }
.button-row .btn-primary { padding: 14px 38px; font-size: 15px; }
.button-row .btn-ghost { padding: 14px 30px; }

/* ---------------- responsive ---------------- */

@media (max-width: 620px) {
  #hud { padding: calc(var(--safe-t) + 12px) calc(var(--safe-r) + 14px) calc(var(--safe-b) + 12px) calc(var(--safe-l) + 16px); }
  .combo { top: calc(var(--safe-t) + 4px); }
  .combo-ring { width: 62px; height: 62px; }
  #comboMult { font-size: 18px; }
  .combo-cap { font-size: 6.5px; }
  .icon-btn { width: 34px; height: 34px; }
  .icon-btn svg { width: 16px; height: 16px; }
  .best-line { font-size: 8.5px; }
  .hint { bottom: calc(var(--safe-b) + 105px); font-size: 9.5px; letter-spacing: .2em; }
  .storm-panel { width: min(330px, 82vw); bottom: calc(var(--safe-b) + 12px); }
  .storm-btn .key { display: none; }
  .features { gap: 0; }
  .feature-copy { font-size: 9px; }
  .menu-foot { gap: 7px; font-size: 8px; }
  .panel { border-radius: 24px; }
  .panel::after { border-radius: 19px; }
}

@media (max-height: 680px) {
  .title { font-size: clamp(52px, 10vh, 84px); }
  .tagline { margin-top: 12px; }
  .lede { display: none; }
  .features { margin: 16px 0 18px; padding: 10px 4px; }
  .panel { padding-top: 24px; padding-bottom: 22px; }
  .menu-foot { margin-top: 14px; }
  .combo-ring { width: 62px; height: 62px; }
}

@media (max-height: 560px) and (orientation: landscape) {
  .title { font-size: 56px; }
  .tagline, .lede, .features, .menu-foot { display: none; }
  .panel { padding: 20px 30px; width: min(460px, 90vw); }
  .btn-primary { margin-top: 18px; padding: 13px 48px; }
  .combo { top: calc(var(--safe-t) + 0px); }
  .combo-ring { width: 56px; height: 56px; }
  .hint { bottom: calc(var(--safe-b) + 88px); }
}

@media (prefers-reduced-motion: reduce) {
  .btn-primary, .storm-btn.ready, .new-best, .hint { animation: none !important; }
}

